/**
 * `defineSkill` — authored at `agent/skills/<name>.ts`.
 *
 * Most skills are plain markdown files (`agent/skills/<name>.md`) or packaged
 * directories (`agent/skills/<name>/SKILL.md` plus sibling files). Reach for
 * `defineSkill` when markdown can't express what you need, such as generated
 * content or inline sibling files:
 *
 * ```ts
 * import { defineSkill } from "@grok/agent-sdk/skills";
 *
 * export default defineSkill({
 *   description: "Research unfamiliar topics before answering.",
 *   markdown: "Gather evidence first, then answer with the key facts.",
 *   files: { "references/checklist.md": "# Checklist\n\n- Find sources.\n" },
 * });
 * ```
 */
import { brandDefinition } from "./internal/brand.js";
export function defineSkill(config) {
    return brandDefinition("skill", config);
}
